let last = performance.now();
function frame(now) {
  const dt = (now - last) / 1000;   // 초 단위 경과 시간
  last = now;
  update(dt);
  render();
  requestAnimationFrame(frame);
}
requestAnimationFrame(frame);

// 나쁨: 프레임이 빠를수록 빨라진다
x += 5;

// 좋음: 초당 300px 로 일정
x += 300 * dt;

let acc = 0;
const STEP = 1 / 60;
function update(dt) {
  acc += Math.min(dt, 0.25);
  while (acc >= STEP) { physics(STEP); acc -= STEP; }   // 항상 같은 크기
}
